package com.google.gson.stream;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void testValue_NaN() throws IOException {
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value(Double.NaN);
        assertEquals("{\"NaN\":null}", writer.toString());
    }

    @Test
    public void testValue_Infinity() throws IOException {
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value(Double.POSITIVE_INFINITY);
        assertEquals("{\"Infinity\":null}", writer.toString());
    }

    @Test
    public void testValue_Infinity_negative() throws IOException {
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value(Double.NEGATIVE_INFINITY);
        assertEquals("{\"-Infinity\":null}", writer.toString());
    }

    @Test
    public void testValue_Finite() throws IOException {
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value(123.456);
        assertEquals("{\"123.456\":123.456}", writer.toString());
    }

    @Test
    public void testValue_Null() {
        assertThrows(IllegalArgumentException.class, () -> new JsonWriter(null).value(123.456));
    }

    @Test
    public void testValue_Null_Writer() throws IOException {
        Writer writer = null;
        JsonWriter jsonWriter = new JsonWriter(writer);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(123.456));
    }

    @Test
    public void testValue_Null_Gson() throws IOException {
        Gson gson = new GsonBuilder().create();
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = gson.getJsonWriter(writer);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(123.456));
    }

    @Test
    public void testValue_Null_GsonBuilder() throws IOException {
        Gson gson = new GsonBuilder().create();
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = gson.getJsonWriter(writer);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(123.456));
    }

    @Test
    public void testValue_Null_GsonBuilder_Local() throws IOException {
        Gson gson = new GsonBuilder().create();
        Writer writer = new StringWriter();
        JsonWriter jsonWriter = gson.getJsonWriter(writer);
        Locale.setDefault(Locale.US);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(123.456));
    }
}
